components.css:
.ds-table-filters { display: grid; grid-template-columns: minmax(220px, 1.5fr) 1fr 1.2fr 1fr auto; align-items: end; gap: 12px; }
.ds-table-filters label { display: grid; gap: 8px; color: var(--muted); font-size: 12px; }
.ds-table-filters input, .ds-table-filters select { width: 100%; min-width: 0; height: 44px; padding: 8px 10px; border: 1px solid #686868; background: var(--field); color: var(--text); font-size: 13px; }
.ds-table-filters input::placeholder { color: var(--muted); opacity: 1; }
.ds-quiet-button { min-height: 44px; padding: 8px 14px; border: 1px solid #686868; background: var(--surface); font-size: 13px; white-space: nowrap; }
.ds-quiet-button:hover:not(:disabled) { background: var(--hover); border-color: var(--muted); }
.ds-quiet-button:disabled { color: var(--muted); border-color: var(--line); background: var(--bg); }
.ds-table-result-line { display: flex; justify-content: space-between; flex-wrap: wrap; gap: 8px 24px; align-items: center; min-height: 64px; font-size: 12px; color: var(--muted); }
.ds-table-result-line a { display: inline-flex; align-items: center; min-height: 44px; }
.ds-feature-scroll { border-top: 1px solid var(--line); }
.ds-feature-table { width: 100%; min-width: 1040px; border-collapse: collapse; table-layout: fixed; font-size: 13px; line-height: 1.6; }
.ds-feature-table th, .ds-feature-table td { padding: 16px 14px; border-bottom: 1px solid var(--line); text-align: left; vertical-align: top; overflow-wrap: anywhere; }
.ds-feature-table thead th { padding-block: 0; background: var(--surface); color: var(--muted); font-size: 12px; font-weight: 400; vertical-align: middle; }
.ds-feature-table thead th:nth-child(1) { width: 22%; }
.ds-feature-table thead th:nth-child(2) { width: 15%; }
.ds-feature-table thead th:nth-child(3) { width: 8%; }
.ds-feature-table thead th:nth-child(4) { width: 15%; }
.ds-feature-table thead th:nth-child(5) { width: 33%; }
.ds-feature-table thead th:nth-child(6) { width: 7%; }
.ds-feature-table thead button { display: flex; align-items: center; justify-content: space-between; gap: 8px; width: 100%; min-height: 48px; padding: 0; border: 0; background: transparent; color: inherit; text-align: left; font-size: inherit; }
.ds-feature-table thead button:hover:not(:disabled) { color: var(--text); }
.ds-feature-table tbody th { font-weight: 400; }
.ds-feature-table tbody tr:hover { background: #222; }
.ds-feature-note { color: var(--muted); }
.ds-proof-note { display: block; margin-top: 5px; color: var(--muted); font-size: 12px; }
.ds-sort-mark { width: 7px; height: 7px; flex-shrink: 0; border-right: 1px solid currentColor; border-bottom: 1px solid currentColor; transform: rotate(45deg); opacity: .65; }
[aria-sort="ascending"] .ds-sort-mark { transform: rotate(225deg); opacity: 1; color: var(--text); }
[aria-sort="descending"] .ds-sort-mark { opacity: 1; color: var(--text); }
.ds-feature-table thead button:disabled .ds-sort-mark { display: none; }
.ds-table-pagination { display: flex; align-items: center; justify-content: flex-end; gap: 16px; margin-top: 24px; font-size: 12px; color: var(--muted); }
.ds-table-result-line, .ds-compatibility-counts, .ds-table-pagination { font-variant-numeric: tabular-nums; }
.ds-empty-results { padding-block: 32px; font-size: 14px; }
.ds-text-button { padding: 0; min-height: 44px; border: 0; background: transparent; color: var(--text); text-decoration: underline; text-underline-offset: 5px; font-size: inherit; }
.ds-text-button:hover { color: var(--accent); }

.ds-compatibility{color:var(--text);font:16px/1.65 'Noto Sans',sans-serif}.ds-table-scroll{overflow-x:auto}.ds-sr-only{position:absolute;width:1px;height:1px;padding:0;overflow:hidden;clip-path:inset(50%);white-space:nowrap}.ds-status-done{color:#c7d8c7}.ds-status-partial{color:var(--accent)}.ds-status-todo{color:var(--muted)}.ds-compatibility button,.ds-compatibility input,.ds-compatibility select{font-family:inherit;color:inherit;border-radius:0}.ds-compatibility button,.ds-compatibility select{cursor:pointer}.ds-compatibility button:disabled{cursor:default}.ds-compatibility button:focus-visible,.ds-compatibility input:focus-visible,.ds-compatibility select:focus-visible{outline:2px solid var(--accent);outline-offset:3px}.ds-compatibility a{color:inherit;text-underline-offset:5px}.ds-compatibility a:hover{color:var(--accent)}.ds-compatibility a:focus-visible,.ds-table-scroll:focus-visible{outline:2px solid var(--accent);outline-offset:5px}.ds-table-result-line p{margin:0}.ds-proof-note{display:block;margin-top:5px;color:var(--muted);font-size:12px}@media(max-width:1050px){.ds-table-filters{grid-template-columns:repeat(3,minmax(0,1fr))}.ds-feature-search{grid-column:span 2}}@media(max-width:760px){.ds-table-filters{grid-template-columns:repeat(2,minmax(0,1fr))}.ds-table-filters .ds-quiet-button{justify-self:start}.ds-feature-table thead th:nth-child(1){width:17%}.ds-feature-table thead th:nth-child(4){width:20%}}@media(max-width:480px){.ds-table-filters{gap:16px 10px}.ds-table-filters label:last-of-type{grid-column:1}.ds-table-filters .ds-quiet-button{width:100%}}

.ds-sampler-roadmap { padding-block: 8px; }
.ds-sampler-phase { display: grid; grid-template-columns: 210px minmax(0, 1fr); gap: 48px; margin-bottom: 44px; }
.ds-sampler-phase h2 { padding-top: 18px; font-size: 24px; }
.ds-sampler-list { min-width: 0; border-top: 1px solid var(--line); }
.ds-sampler-row { display: grid; grid-template-columns: minmax(0, 1fr) 150px 110px; gap: 24px; align-items: baseline; padding-block: 20px; border-bottom: 1px solid var(--line); }
.ds-sampler-row h3 { font-size: 18px; }
.ds-sampler-row > span, .ds-sampler-row > a { font-size: 13px; }
.ds-sampler-row > span:not(.ds-status-partial) { color: var(--muted); }
.ds-sampler-row > a { justify-self: end; }
.ds-sampler-scope { padding: 8px 0; border: 0; }
.ds-sampler-scope summary { width: fit-content; color: var(--muted); font-size: 13px; }
.ds-sampler-scope p { color: var(--muted); font-size: 14px; }
.ds-sampler-roadmap{color:var(--text);font:16px/1.65 'Noto Sans',sans-serif}.ds-sampler-roadmap h2,.ds-sampler-roadmap h3{margin:0;font-weight:400;line-height:1.2;text-wrap:balance}.ds-sampler-roadmap h2{letter-spacing:-.02em}.ds-status-partial{color:var(--accent)}.ds-sampler-roadmap a{color:inherit;text-underline-offset:5px}.ds-sampler-roadmap a:hover{color:var(--accent)}.ds-sampler-roadmap a:focus-visible,.ds-sampler-scope summary:focus-visible{outline:2px solid var(--accent);outline-offset:5px}.ds-sampler-scope summary{display:list-item;align-content:center;cursor:pointer;min-height:44px}.ds-sampler-scope p{max-width:70ch;margin:16px 0 8px}@media(max-width:1050px){.ds-sampler-phase{grid-template-columns:160px minmax(0,1fr);gap:32px}.ds-sampler-row{grid-template-columns:minmax(0,1fr) 130px;gap:12px}.ds-sampler-row>a{grid-column:1/-1;justify-self:start}}@media(max-width:760px){.ds-sampler-phase{grid-template-columns:1fr;gap:20px;margin-bottom:32px}.ds-sampler-phase h2{padding-top:0}}@media(max-width:480px){.ds-sampler-row{grid-template-columns:minmax(0,1fr) 120px}}
